const raw = $input.first().json;
const b = raw.body || raw;
const source = b.source || 'chatgpt';
const title = b.title || 'Untitled';
const content = b.content || '';
const forceFailure = b.type_hint === 'force-failure-buffer-test';
const date = new Date().toISOString().slice(0, 10);

const prompt = `You are a GTD/PARA knowledge system processor.

1. CLASSIFY the note:
   - para_type: project (clear finish line), area (ongoing), resource (reference), or inbox (unclear)
   - confidence: 0.0-1.0 (how sure are you about the classification?)

2. SCORE the note:
   - signal_quality: 0.0-1.0 (how actionable and valuable is this?)
   - Consider: specificity, clarity, potential impact, urgency
   - 0.9+ = concrete, actionable, high-impact
   - 0.5-0.8 = somewhat clear but needs refinement
   - <0.5 = vague, abstract, low-value, or unclear

3. SUMMARIZE in 1-2 sentences

4. LIST 3-5 key points

User context: builds SaaS products, runs ministry, automates workflows.

Respond ONLY with valid JSON (no markdown fences):
{"title":string,"para_type":"project|area|resource|inbox","confidence":0.0-1.0,"signal_quality":0.0-1.0,"summary":string,"key_points":[string]}

Content to process:
Source: ${source}
Title: ${title}
Content:
${content}`;

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }]
});

return [{ json: { geminiBody, source, title, content, date, forceFailure } }];

function utf8ToBase64(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.charCodeAt(i);
    if (code < 0x80) { bytes.push(code); } 
    else if (code < 0x800) { bytes.push(0xc0 | (code >> 6)); bytes.push(0x80 | (code & 0x3f)); } 
    else if (code >= 0xd800 && code <= 0xdbff) { i++; const next = str.charCodeAt(i); const fullCode = 0x10000 + (((code & 0x3ff) << 10) | (next & 0x3ff)); bytes.push(0xf0 | (fullCode >> 18)); bytes.push(0x80 | ((fullCode >> 12) & 0x3f)); bytes.push(0x80 | ((fullCode >> 6) & 0x3f)); bytes.push(0x80 | (fullCode & 0x3f)); } 
    else { bytes.push(0xe0 | (code >> 12)); bytes.push(0x80 | ((code >> 6) & 0x3f)); bytes.push(0x80 | (code & 0x3f)); }
  }
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let output = "";
  for (let i = 0; i < bytes.length; i += 3) { const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2]; output += chars[a >> 2]; output += chars[((a & 3) << 4) | ((b ?? 0) >> 4)]; output += b === undefined ? "=" : chars[((b & 15) << 2) | ((c ?? 0) >> 6)]; output += c === undefined ? "=" : chars[c & 63]; }
  return output;
}
const orig = $("Build Gemini Body").first().json, title = orig.title || "Untitled Capture", content = orig.content || "", source = orig.source || "chatgpt", date = orig.date, forceFailure = orig.forceFailure === true;
const gmini = $json;
const cls = gmini.candidates?.[0]?.content?.parts?.[0]?.text;
const classifyError = gmini.error?.message || gmini.error?.error?.message || '';
let ptype = "inbox", conf = 0.5, sq = 0.5, summ = "", kpts = [];
let failureStage = '';
let errorSummary = '';

if (forceFailure || classifyError || !cls) {
  failureStage = 'gemini-classify';
  errorSummary = forceFailure ? 'Forced failure-buffer verification' : (classifyError || 'Gemini classification returned no usable content');
  ptype = 'inbox';
  conf = 0;
  sq = 0;
  summ = 'Failed to classify capture; preserved for retry.';
  kpts = [];
} else {
  try { const p = JSON.parse(cls); ptype = p.para_type || "inbox"; conf = p.confidence || 0.5; sq = p.signal_quality || 0.5; summ = p.summary || ""; kpts = p.key_points || []; } catch (e) { failureStage = 'parse'; errorSummary = 'Gemini returned invalid JSON'; ptype = 'inbox'; conf = 0; sq = 0; summ = 'Failed to parse Gemini response; preserved for retry.'; kpts = []; }
}
const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "untitled-capture";
const isFailed = Boolean(failureStage);
const inboxPrefix = ($env.MIND_INBOX_PATH || 'inbox/new').replace(/^\/+|\/+$/g, '') || 'inbox/new';
const failedPrefix = ($env.MIND_FAILED_PATH || 'inbox/failed').replace(/^\/+|\/+$/g, '') || 'inbox/failed';
const file = `${isFailed ? failedPrefix : inboxPrefix}/${date}-${slug}.md`;
const md = `---\ntype: ${isFailed ? 'failed-capture' : 'capture'}\nsource: ${source}\nstatus: ${isFailed ? 'needs-retry' : 'saved'}\npara_type: ${ptype}\nconfidence: ${conf}\nsignal_quality: ${sq}\ntitle: ${JSON.stringify(title)}\ncreated: ${new Date().toISOString()}\n${isFailed ? `failure_stage: ${failureStage || 'unknown'}\nerror_summary: ${JSON.stringify(errorSummary || 'unknown')}\n` : ''}---\n\n# ${title}\n\n## Summary\n${summ}\n\n## Key Points\n${kpts.map(p => `- ${p}`).join('\n')}\n\n## Content\n${content}\n`;
const b64 = utf8ToBase64(md);
return [{json: {...orig, title, content, source, date, filepath: file, markdown: md, base64: b64, paraType: ptype, confidence: conf, summary: summ, keyPoints: kpts, failureStage, errorSummary, isFailed, forceFailure}}];

const processed = $('Build Processed Note').first().json;
const current = $json;

let sha = undefined;

if (current && current.sha && typeof current.sha === "string") {
  sha = current.sha;
}

return [{
  json: {
    ...processed,
    sha,
    fileExists: Boolean(sha),
  }
}];

